// function electricityBill(units) mein units do
// <=100: free, 101-300: Rs.5/unit, 301-500: Rs.8/unit, >500: Rs.10/unit
// Total bill return karo

solution:
function electricityBill(units) {
  if (units <= 100) return 0
  else if (units <= 300) return (units - 100) * 5
  else if (units <= 500) return 200 * 5 + (units - 300) * 8
  else return 200 * 5 + 200 * 8 + (units - 500) * 10
}
